fullText:
body,main{
    height: 700px;
}
section{
    width: 40%;
    float: left;
    height: 100%;
}
aside{
    width: 60%;
    float: left;
    height: 100%;
}
iframe{
    width: 100%;
    height: 100%;
}
label{
    display: inline-block;
    width: 10%;
    margin: 1.5%;
    font-weight: bold;
}

#pass label {
    display: inline-block;
    width: 40%;
    margin: 1.5%;
    font-weight: bold;
}
#btn{
    text-align: right;
    margin-right: 36.5%;
}
ul{
    padding-left: 60px;
    margin-top: 60px;
}
#formcom label,#formcom select{
    width: 20%;
    margin-bottom: 10%;
}

